// Fault codes in plain English: what a code means, how urgent it is, what to
// check. Generic OBD-II codes come from the bundled library
// (Resources/code-library.json, generated by tools/make_code_library.py).
// BMW's own 6-digit codes have no public texts, so they're explained from the
// module that stored them. General guidance, not a diagnosis.
import Foundation

/// How soon a fault needs attention.
public enum Severity: String, Codable, CaseIterable, Comparable, Sendable {
    case info, soon, now, stop

    public var label: String {
        switch self {
        case .info: return "Not urgent"
        case .soon: return "Check soon"
        case .now: return "Check now"
        case .stop: return "Stop safely"
        }
    }

    private var rank: Int { Severity.allCases.firstIndex(of: self) ?? 0 }
    public static func < (a: Severity, b: Severity) -> Bool { a.rank < b.rank }
}

/// One entry of the code library.
public struct CodeInfo: Codable, Equatable, Sendable {
    public let code: String
    public let title: String
    public let system: String
    public let severity: Severity
    public let meaning: String
    public let causes: [String]
    public let checks: [String]
    public let drive: String
    public let ignored: String?
}

public struct CodeLibrary: Sendable {
    public let version: Int
    public let entries: [String: CodeInfo]

    public init(version: Int, entries: [String: CodeInfo]) {
        self.version = version
        self.entries = entries
    }

    /// The library shipped with the app. Empty (never a crash) if it can't load.
    public static let shared = CodeLibrary.loadBundled()

    public static func loadBundled() -> CodeLibrary {
        guard let url = Bundle.module.url(forResource: "code-library", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let library = try? decode(data) else { return CodeLibrary(version: 0, entries: [:]) }
        return library
    }

    public static func decode(_ data: Data) throws -> CodeLibrary {
        struct File: Decodable { let version: Int; let codes: [CodeInfo] }
        let file = try JSONDecoder().decode(File.self, from: data)
        return CodeLibrary(version: file.version,
                           entries: Dictionary(file.codes.map { ($0.code, $0) }, uniquingKeysWith: { a, _ in a }))
    }

    public func info(_ code: String) -> CodeInfo? { entries[code.uppercased()] }
}

// MARK: - state of a stored code

public enum CodeState: String, CaseIterable, Sendable {
    case active, stored, pending, permanent, earlier, notTested

    public var label: String {
        switch self {
        case .active: return "Active now"
        case .stored: return "Stored"
        case .pending: return "Pending"
        case .permanent: return "Permanent"
        case .earlier: return "Failed earlier"
        case .notTested: return "Not tested yet"
        }
    }

    public var explanation: String {
        switch self {
        case .active: return "The fault was present in the module's latest test."
        case .stored: return "Confirmed and saved in the module's memory. It may or may not be present now."
        case .pending: return "Seen recently but not confirmed. If it happens again, it becomes a stored code."
        case .permanent:
            return "An emissions code only the engine computer can clear, once it has confirmed the repair "
                + "over several drives. Clearing tools can't erase it."
        case .earlier: return "Failed at some point since the codes were last cleared, but isn't stored as confirmed."
        case .notTested: return "Not a fault: the module hasn't run this test yet since the codes were last cleared."
        }
    }

    /// ISO 14229 status byte -> states, most important first.
    public static func states(fromStatus s: UInt8) -> [CodeState] {
        var out: [CodeState] = []
        if s & 0x01 != 0 { out.append(.active) }
        if s & 0x08 != 0 { out.append(.stored) }
        if s & 0x04 != 0 { out.append(.pending) }
        if out.isEmpty && s & 0x22 != 0 { out.append(.earlier) }
        return out.isEmpty ? [.notTested] : out
    }

    /// What each ISO 14229 status bit means.
    public static let statusBits: [(bit: UInt8, meaning: String)] = [
        (0x01, "Failed in the latest test"),
        (0x02, "Failed during this drive"),
        (0x04, "Pending: seen, not confirmed yet"),
        (0x08, "Confirmed and stored"),
        (0x10, "Not tested since codes were last cleared"),
        (0x20, "Failed at least once since codes were last cleared"),
        (0x40, "Not tested yet during this drive"),
        (0x80, "Asked for a warning light"),
    ]
}

/// A code read from the car.
public struct FoundCode: Identifiable, Hashable, Sendable {
    public enum Source: String, Sendable {
        case faultMemory = "Module fault memory"
        case obd = "OBD-II (emissions)"
    }

    public let module: UInt16
    /// "P0302" for OBD codes, "4B1C00" (6 hex digits) for BMW fault memory.
    public let code: String
    public let isSAE: Bool
    /// ISO 14229 status byte (fault memory only).
    public let status: UInt8?
    public var states: [CodeState]
    public let source: Source

    public init(module: UInt16, code: String, isSAE: Bool, status: UInt8?, states: [CodeState], source: Source) {
        self.module = module
        self.code = code
        self.isSAE = isSAE
        self.status = status
        self.states = states
        self.source = source
    }

    /// From a ReadDTCInformation record.
    public init(module: UInt16, record: UDS.DTCRecord) {
        self.init(module: module, code: String(format: "%06X", record.dtc), isSAE: false, status: record.status,
                  states: CodeState.states(fromStatus: record.status), source: .faultMemory)
    }

    public var id: String { String(format: "%02X:", module) + (source == .obd ? "obd:" : "fm:") + code }
    public var isFault: Bool { states.contains { $0 != .notTested } }
    public var isActive: Bool { states.contains(.active) }
    public var warningLight: Bool { (status ?? 0) & 0x80 != 0 }
    public var stateText: String { states.map(\.label).joined(separator: " · ") }

    /// Plain-English explanation of this code, using the module and state it was found with.
    public var explanation: CodeExplanation { CodeExplainer.explain(code, module: module, states: states) }
}

// MARK: - modules

/// What a module does, for codes that only BMW can name.
public struct ModuleInfo: Equatable, Sendable {
    public enum Kind: String, Sendable { case safety, drivetrain, network, body, cluster, infotainment, unknown }

    public let address: UInt16
    public let short: String
    public let name: String
    /// What it handles, as a phrase: "fuel, ignition, turbo boost and emissions."
    public let role: String
    public let kind: Kind
    /// Driving advice when this module has a fault stored.
    public let drive: String

    public static func unknown(_ address: UInt16) -> ModuleInfo {
        ModuleInfo(address: address, short: String(format: "0x%02X", address),
                   name: String(format: "Module 0x%02X", address),
                   role: "a job this app doesn't know yet.", kind: .unknown,
                   drive: "This app doesn't know this module, so look up the code before deciding.")
    }

    /// Urgency of a BMW code from this module, from the module's job and the code's state.
    public func severity(for states: [CodeState]) -> Severity {
        let active = states.contains(.active)
        switch kind {
        case .safety: return active ? .now : .soon
        case .drivetrain, .network, .body, .unknown: return active ? .soon : .info
        case .cluster, .infotainment: return .info
        }
    }
}

// MARK: - explanations

public struct CodeExplanation: Equatable, Sendable {
    public enum Kind: Equatable, Sendable {
        case known        // in the library
        case category     // a valid SAE code that isn't in the library
        case bmw          // BMW's own code number
        case invalid
    }

    public let code: String
    public let kind: Kind
    public let title: String
    public let system: String
    /// nil when the urgency can't be known from the code.
    public let severity: Severity?
    public let meaning: String
    public let causes: [String]
    public let checks: [String]
    public let drive: String
    public let ignored: String?
    /// Where the explanation comes from, shown under it.
    public let source: String
    /// Web search for the code, for codes the app can't fully explain.
    public let searchQuery: String
}

public enum CodeExplainer {
    /// "p 0171" -> "P0171", "0x4b1c00" -> "4B1C00"; nil if it isn't a code.
    public static func normalize(_ text: String) -> (code: String, isSAE: Bool)? {
        var s = text.uppercased().filter { !" -_.:".contains($0) }
        if s.hasPrefix("0X") { s.removeFirst(2) }
        if OBD.saeBytes(s) != nil { return (s, true) }
        if (4...6).contains(s.count), s.allSatisfy({ $0.isHexDigit && $0.isASCII }) { return (s, false) }
        return nil
    }

    private static let unknownDrive =
        "Urgency unknown: watch for warning lights and changes in how the car drives, and look the code up."

    public static func explain(_ text: String, module: UInt16? = nil, states: [CodeState] = [],
                               library: CodeLibrary = .shared) -> CodeExplanation {
        guard let normalized = normalize(text) else {
            return CodeExplanation(
                code: text, kind: .invalid, title: "Not a fault code", system: "",
                severity: nil,
                meaning: "Fault codes look like P0171 (a letter and 4 characters) or 4B1C00 (BMW's own, 6 characters).",
                causes: [], checks: [], drive: "", ignored: nil, source: "", searchQuery: text)
        }
        let code = normalized.code
        let moduleInfo = module.map(BMWModules.describe)
        if normalized.isSAE {
            let search = "\(code) " + (module == nil ? "OBD code" : "BMW")
            if let info = library.info(code) {
                return CodeExplanation(
                    code: code, kind: .known, title: info.title, system: info.system,
                    severity: info.severity, meaning: info.meaning, causes: info.causes, checks: info.checks,
                    drive: info.drive, ignored: info.ignored,
                    source: "Standard OBD-II meaning: the same on every car. General guidance, not a diagnosis.",
                    searchQuery: search)
            }
            let c = category(code)
            let meaning = c.manufacturer
                ? "A manufacturer-specific code: its meaning is set by the carmaker, not the OBD standard. "
                    + "It's in the \(c.system.lowercased()) area. On a BMW, MHD (engine codes), BimmerLink "
                    + "or a dealer tool shows the description."
                : "A standard code that isn't in this app's list yet. Its letter and digits say it's about: "
                    + "\(c.system.lowercased())."
            return CodeExplanation(
                code: code, kind: .category, title: c.title, system: c.system, severity: nil,
                meaning: meaning, causes: [],
                checks: ["Search the web for the code and your car model",
                         "Have it read with a tool that shows the full description"],
                drive: unknownDrive, ignored: nil,
                source: "From the code's structure (SAE J2012) only.", searchQuery: search)
        }

        let where_ = moduleInfo.map { "the \($0.name)" } ?? "a module"
        let search = "BMW " + (moduleInfo.map { $0.short + " " } ?? "") + "fault code \(code)"
        var meaning = "This is BMW's own number for a fault stored in \(where_). BMW doesn't publish what "
            + "its codes mean, so this app can't show the description."
        if let m = moduleInfo, m.kind != .unknown { meaning += " The \(m.short) handles \(m.role)" }
        return CodeExplanation(
            code: code, kind: .bmw, title: "BMW code " + code,
            system: moduleInfo?.name ?? "BMW module", severity: moduleInfo?.severity(for: states),
            meaning: meaning, causes: [],
            checks: ["Search the web for the module and the code",
                     "MHD (for engine codes), BimmerLink or a BMW dealer tool can show BMW's own description",
                     "Scan again after a drive: a code that isn't active may be old history"],
            drive: moduleInfo?.drive ?? unknownDrive, ignored: nil,
            source: "Explained from the module that stored it; BMW's code texts aren't public.",
            searchQuery: search)
    }

    /// What an SAE code's letter and digits say (SAE J2012 layout).
    public static func category(_ code: String) -> (title: String, system: String, manufacturer: Bool) {
        let c = Array(code.uppercased())
        guard c.count == 5 else { return ("Unknown code", "Unknown", false) }
        let d1 = c[1], d2 = c[2]
        switch c[0] {
        case "P":
            let manufacturer = d1 == "1" || (d1 == "3" && "0123".contains(d2))
            let system: String
            if d1 == "0" {
                switch d2 {
                case "0": system = "Fuel and air metering, and emission controls"
                case "1": system = "Fuel and air metering"
                case "2": system = "Fuel and air metering (injector circuits)"
                case "3": system = "Ignition system or misfire"
                case "4": system = "Emission controls"
                case "5": system = "Vehicle speed, idle control and inputs"
                case "6": system = "Engine computer and output circuits"
                case "7", "8", "9": system = "Transmission"
                default: system = "Hybrid propulsion"
                }
            } else if d1 == "2" {
                switch d2 {
                case "3": system = "Ignition system"
                case "4": system = "Emission controls"
                case "5": system = "Inputs"
                case "6": system = "Engine computer and output circuits"
                case "7": system = "Transmission"
                default: system = "Fuel and air metering, and emission controls"
                }
            } else {
                system = "Engine and transmission (powertrain)"
            }
            return (manufacturer ? "Manufacturer-specific powertrain code" : "Powertrain code", system, manufacturer)
        case "C":
            let manufacturer = d1 == "1" || d1 == "2"
            return (manufacturer ? "Manufacturer-specific chassis code" : "Chassis code",
                    "Chassis: brakes, ABS, stability control, suspension and steering", manufacturer)
        case "B":
            let manufacturer = d1 == "1" || d1 == "2"
            return (manufacturer ? "Manufacturer-specific body code" : "Body code",
                    "Body: airbags, seats, lights, climate and comfort features", manufacturer)
        default:
            let manufacturer = d1 == "1" || d1 == "2"
            var system = "Network: communication between modules"
            if d1 == "0" {
                switch d2 {
                case "0": system = "Network wiring (data bus)"
                case "1", "2": system = "Network: lost communication with a module"
                case "3": system = "Network: software mismatch between modules"
                case "4": system = "Network: invalid data from a module"
                default: break
                }
            }
            return (manufacturer ? "Manufacturer-specific network code" : "Network code", system, manufacturer)
        }
    }
}
